// WF-08 | Stage 2 - Data Processing
// Turns the input of BOTH triggers (schedule poll / manual webhook) into one envelope.
const DEFAULT_ORG_ID = '11111111-1111-4111-8111-111111111111';
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});
const raw = $json;

let trigger = 'schedule';
try { if ($('01b Webhook Manual Enrich').isExecuted) trigger = 'webhook'; } catch (e) { /* ignore */ }

let eventId = null, leadId = '', organizationId = DEFAULT_ORG_ID, correlationId = '', force = false;
if (trigger === 'webhook') {
  const b = raw.body || {};
  leadId = String(b.leadId || '').trim();
  organizationId = String(b.organizationId || DEFAULT_ORG_ID).trim();
  force = b.force === true;
  correlationId = String((raw.headers || {})['x-correlation-id'] || b.correlationId || '').trim();
} else {
  eventId = raw.event_id || null;
  leadId = String(raw.lead_id || '').trim();
  organizationId = String(raw.organization_id || DEFAULT_ORG_ID).trim();
  correlationId = String(raw.correlation_id || '').trim();
}
if (!UUID_RE.test(correlationId)) correlationId = uuid();

const errors = [];
if (!UUID_RE.test(leadId)) errors.push({ field: 'leadId', code: 'INVALID_UUID', message: 'leadId must be a UUID' });
if (!UUID_RE.test(organizationId)) {
  errors.push({ field: 'organizationId', code: 'INVALID_UUID', message: 'organizationId must be a UUID' });
  organizationId = DEFAULT_ORG_ID;
}

return {
  json: {
    valid: errors.length === 0,
    errors,
    trigger,
    eventId,
    leadId,
    organizationId,
    correlationId,
    force,
    runInput: { trigger, eventId, leadId, force },
  },
};

