// WF-08 | Stage 7 - Decision (prepare): decide whether this lead needs enrichment.
const d = $('02 Normalize Input').item.json;
const lead = ($json.body && $json.body.data) || {};          // Core API wraps responses in { data, meta }
const meta = lead.metadata && typeof lead.metadata === 'object' ? lead.metadata : {};
const prev = meta.enrichment || null;
const FRESH_DAYS = 30;                                         // do not re-enrich inside this window (saves API credits)
const FREE_MAIL = ['gmail.com', 'googlemail.com', 'yahoo.com', 'yahoo.com.vn', 'outlook.com', 'hotmail.com',
  'live.com', 'msn.com', 'icloud.com', 'me.com', 'proton.me', 'protonmail.com', 'aol.com', 'gmx.com', 'mail.com',
  'zoho.com', 'qq.com', '163.com'];

const email = String(lead.email || '').trim().toLowerCase();
const at = email.lastIndexOf('@');
const domain = at > 0 ? email.slice(at + 1) : '';
const isFreeMail = FREE_MAIL.includes(domain);

let action = 'enrich';
let skipReason = null;
if (!email) {
  action = 'skip'; skipReason = 'NO_EMAIL';
} else if (!d.force && prev && prev.enrichedAt && Date.now() - Date.parse(prev.enrichedAt) < FRESH_DAYS * 86400000) {
  action = 'skip'; skipReason = 'RECENTLY_ENRICHED';
}

return {
  json: {
    action,
    skipReason,
    leadId: lead.id,
    organizationId: lead.organization_id,
    email,
    domain: isFreeMail ? '' : domain,
    isFreeMail,
    companyName: lead.company_name || '',
    existingMetadata: meta,
  },
};

