// WF-08 | Stage 8 - Transformation: build the enrichment record + the PATCH body for Core API.
// Input = Hunter response (node 07).
const plan = $('06 Plan Enrichment').item.json;
const sc = $json.statusCode;
if (sc !== 200 && sc !== 404) throw new Error('Enrichment API failed: HTTP ' + sc);   // 401/429/5xx -> run failed, poller retries
const data = (sc === 200 && $json.body && $json.body.data) || {};
const p = data.person || null;
const c = data.company || null;
const emp = p && p.employment ? p.employment : {};
const m = c && c.metrics ? c.metrics : {};
const cat = c && c.category ? c.category : {};
const geo = c && c.geo ? c.geo : {};

const company = c ? {
  name: c.name || null,
  domain: c.domain || null,
  size: m.employeesRange || (m.employees != null ? String(m.employees) : null),
  employeeCount: typeof m.employees === 'number' ? m.employees : null,
  industry: cat.industry || cat.sector || null,
  founded: c.foundedYear || null,
  type: c.type || null,
  linkedinUrl: c.linkedin && c.linkedin.handle ? 'https://www.linkedin.com/' + c.linkedin.handle : null,
  location: { city: geo.city || null, country: geo.country || null },
} : null;
const jobTitle = emp.title || null;
const status = company && (company.name || company.size) ? 'enriched' : (jobTitle ? 'partial' : 'not_found');
const enrichment = {
  status,
  provider: 'hunter',
  enrichedAt: new Date().toISOString(),
  jobTitle,
  seniority: emp.seniority || null,
  company: status === 'not_found' ? null : company,
};

// Core API PATCH replaces `metadata` as a whole -> send the old metadata + the new enrichment key.
const leadPatch = { metadata: { ...plan.existingMetadata, enrichment } };
if (!plan.companyName && company && company.name) leadPatch.companyName = company.name;

return {
  json: {
    leadId: plan.leadId,
    organizationId: plan.organizationId,
    enrichment,
    leadPatch,
    profileAttributes: { enrichment },
  },
};

