WITH upd AS (
  UPDATE customer_profiles SET attributes = attributes || $3::jsonb, updated_at = NOW()
  WHERE lead_id = $1::uuid RETURNING id
), ins AS (
  INSERT INTO customer_profiles (organization_id, lead_id, lifecycle_stage, attributes)
  SELECT $2::uuid, $1::uuid, 'lead', $3::jsonb WHERE NOT EXISTS (SELECT 1 FROM upd)
  RETURNING id
)
SELECT id FROM (SELECT id FROM upd UNION ALL SELECT id FROM ins) t LIMIT 1;

