        schemaVersion: 1,
        workflow: 'WF-08',
        leadId: b.leadId,
        sourceEventId: d.eventId,
        trigger: d.trigger,
        customerProfileId: $json.id,
        enrichmentStatus: e.status,
        provider: e.provider,
        enrichedAt: e.enrichedAt,
        jobTitle: e.jobTitle,
        seniority: e.seniority,
        company: e.company
          ? { name: e.company.name, domain: e.company.domain, size: e.company.size,
